<script setup lang="ts">
import {getLookups} from '../TransportAndDispatch/api';
import {ref,onMounted,onBeforeUnmount} from 'vue';
import {request,failure,paginated} from '../Administration/api';
import {labels as stateLabels} from '../TransportAndDispatch/presentation';
interface Row {id:string;customer:{id:string;name:string};product:string;execution_status:string;administrative_status:string}
const emit=defineEmits<{denied:[error:unknown]}>();const rows=ref<Row[]>([]),customers=ref<{id:string;name:string}[]>([]),customer=ref(''),status=ref(''),error=ref(''),loading=ref(false),page=ref(1),last=ref(1);let generation=0;
async function load(target=1):Promise<void>{if(loading.value)return;const current=++generation;loading.value=true;error.value='';try{const query=new URLSearchParams({page:String(target)});if(customer.value)query.set('customer_id',customer.value);if(status.value)query.set('execution_status',status.value);const result=await paginated<Row>(`/billing/trips?${query}`);if(current!==generation)return;rows.value=result.data;page.value=result.meta.current_page;last.value=result.meta.last_page;}catch(e){if(current!==generation)return;error.value=failure(e).message;if([401,403].includes(failure(e).status)){rows.value=[];emit('denied',e);}}finally{if(current===generation)loading.value=false;}}
onMounted(async()=>{try{const data=await getLookups('customers');if(generation===0)customers.value=data as {id:string;name:string}[];}catch(e){if(generation===0){error.value=failure(e).message;if([401,403].includes(failure(e).status))emit('denied',e);}return;}if(generation===0)await load();});onBeforeUnmount(()=>generation++);
</script>
<template><section class="space-y-4"><h2 class="text-xl font-semibold">Viajes y clientes · preparación de facturación</h2><p class="notice-info">Consulta administrativa. No crea facturas ni comprobantes legales. Un viaje finalizado no se declara facturable automáticamente: faltan reglas comerciales y monetarias aprobadas.</p><form class="panel flex flex-wrap items-end gap-4" @submit.prevent="load()"><label>Cliente<select v-model="customer" class="field"><option value="">Todos los clientes</option><option v-for="item in customers" :key="item.id" :value="item.id">{{item.name}}</option></select></label><label>Estado de ejecución<select v-model="status" class="field"><option value="">Todos</option><option v-for="state in ['pending','in_progress','completed','cancelled']" :key="state" :value="state">{{stateLabels[state]}}</option></select></label><button class="btn-primary" :disabled="loading">Consultar viajes</button></form><p v-if="loading" role="status">Consultando registros…</p><p v-if="error" role="alert" class="notice-error">{{error}}</p><div class="overflow-x-auto"><table class="w-full text-left text-sm"><thead><tr><th>Cliente</th><th>Viaje</th><th>Producto</th><th>Ejecución</th><th>Cierre</th></tr></thead><tbody><tr v-for="row in rows" :key="row.id"><td class="p-3">{{row.customer.name}}</td><td class="p-3">{{row.id}}</td><td class="p-3">{{row.product}}</td><td class="p-3">{{stateLabels[row.execution_status]}}</td><td class="p-3">{{stateLabels[row.administrative_status]}}</td></tr></tbody></table></div><p v-if="!loading&&!rows.length">No hay viajes para estos filtros.</p><div class="flex gap-3"><button class="btn-secondary" :disabled="loading||page<=1" @click="load(page-1)">Anterior</button><span>Página {{page}} de {{last}}</span><button class="btn-secondary" :disabled="loading||page>=last" @click="load(page+1)">Siguiente</button></div></section></template>
